def dedupe(listings: list[dict]) -> list[dict]:
    def normalize_title(title: str) -> str:
        return " ".join(title.strip().lower().split())

    chosen_index_by_key: dict[tuple[str, int], int] = {}

    for index, listing in enumerate(listings):
        key = (normalize_title(listing["title"]), listing["price"])
        date = listing["date"]

        if key not in chosen_index_by_key:
            chosen_index_by_key[key] = index
        else:
            current_index = chosen_index_by_key[key]
            if date < listings[current_index]["date"]:
                chosen_index_by_key[key] = index

    chosen_indices = set(chosen_index_by_key.values())
    return [listing for index, listing in enumerate(listings) if index in chosen_indices]

