        if not payment:
            continue

        cleaned_price = price_raw.replace(",", "").replace(" ", "")
        if not cleaned_price:
            continue

        try:
            price = int(cleaned_price)
        except ValueError:
            try:
                price = int(float(cleaned_price))
            except ValueError:
                continue

        totals[payment] = totals.get(payment, 0) + price

    return totals

